"use client"; import { useState } from "react"; export default function Page(){const [sent,setSent]=useState(false);return <section className="container max-w-2xl py-16"><p className="text-sm font-bold uppercase tracking-widest text-teal-700">Contact</p><h1 className="mt-3 text-4xl font-extrabold">Questions about this resource?</h1><p className="mt-4 text-slate-600">Send editorial feedback, correction requests, or accessibility concerns. We cannot provide individual medical advice.</p>{sent?<div className="card mt-8 p-6">Thank you. Your message has been prepared for the site team.</div>:<form onSubmit={e=>{e.preventDefault();setSent(true)}} className="card mt-8 grid gap-4 p-6"><label className="text-sm font-bold">Name<input required className="mt-1 w-full rounded-lg border p-3"/></label><label className="text-sm font-bold">Email<input required type="email" className="mt-1 w-full rounded-lg border p-3"/></label><label className="text-sm font-bold">Message<textarea required rows={5} className="mt-1 w-full rounded-lg border p-3"/></label><button className="w-fit rounded-xl bg-teal-700 px-5 py-3 font-bold text-white">Send message</button></form>}</section>}
